// Build Discord notifications from the Klaviyo billing payload.
// Gate: notify on a real reminder or a client failure, never on a duplicate.
// Accepts both send modes: one client per request, or a batch {clients:[...]}.

const RED = 15082283;    // over limit / client failed
const ORANGE = 16097024; // high usage / period ending
const BLUE = 3447003;    // informational

const num = (v) =>
  v === null || v === undefined || Number.isNaN(Number(v))
    ? '—'
    : Number(v).toLocaleString('en-US');

const pct = (v) =>
  v === null || v === undefined || Number.isNaN(Number(v))
    ? '—'
    : `${Number(v).toFixed(1)}%`;

const usage = (used, limit, percent) =>
  limit === null || limit === undefined
    ? `${num(used)} (no limit)`
    : `${num(used)} / ${num(limit)} · ${pct(percent)}`;

function shouldNotify(c) {
  if (!c || typeof c !== 'object') return false;
  if (c.suppressed_duplicate === true) return false;
  return c.success === false || c.should_remind === true;
}

function severity(c) {
  const types = c.alert_types || [];
  if (c.success === false) return RED;
  if (types.some((t) => String(t).startsWith('over_limit'))) return RED;
  if (types.length) return ORANGE;
  return BLUE;
}

function failureEmbed(c) {
  return {
    title: `⚠️ Klaviyo check failed — ${c.client_name}`,
    color: RED,
    description:
      c.error_type === 'auth'
        ? '**Invalid API key.** This client was skipped; its usage is unknown.'
        : `Could not read this account: \`${String(c.error_type || 'unknown')}\``,
    fields: [{ name: 'Detail', value: String(c.error || 'No detail').slice(0, 1000) }],
    footer: { text: `alert ${c.alert_key || 'n/a'}` },
    timestamp: c.checked_at || new Date().toISOString(),
  };
}

function reminderEmbed(c) {
  const days =
    c.days_until_billing === null || c.days_until_billing === undefined
      ? '—'
      : c.days_until_billing < 0
        ? `ended ${Math.abs(c.days_until_billing)}d ago`
        : c.days_until_billing === 0
          ? 'today'
          : `in ${c.days_until_billing} day${c.days_until_billing === 1 ? '' : 's'}`;

  const endDate = c.billing_period_end
    ? String(c.billing_period_end).slice(0, 10)
    : '—';

  const fields = [
    { name: 'Billing period ends', value: `${endDate} (${days})`, inline: true },
    { name: 'Campaigns sent', value: num(c.sent_campaign_count), inline: true },
    {
      name: 'Avg recipients / email',
      value: num(c.average_recipients_per_email),
      inline: true,
    },
    {
      name: 'Profiles',
      value: usage(c.active_profiles, c.profile_limit, c.profile_usage_percent),
      inline: true,
    },
    {
      name: 'Email',
      value: usage(c.email_used, c.email_limit, c.email_usage_percent),
      inline: true,
    },
    {
      name: 'SMS',
      value: usage(c.sms_used, c.sms_limit, c.sms_usage_percent),
      inline: true,
    },
  ];

  // Only surface AI / Reviews when they have actually been used.
  if (Number(c.ai_used) > 0) {
    fields.push({
      name: 'AI credits',
      value: usage(c.ai_used, c.ai_limit, c.ai_usage_percent),
      inline: true,
    });
  }
  if (Number(c.reviews_used) > 0) {
    fields.push({
      name: 'Reviews',
      value: usage(c.reviews_used, c.reviews_limit, c.reviews_usage_percent),
      inline: true,
    });
  }

  const reasons = (c.reasons || []).map((r) => `• ${r}`).join('\n');

  return {
    title: `🔔 Billing review — ${c.client_name}`,
    color: severity(c),
    description: (reasons || '• Flagged for review').slice(0, 4000),
    fields,
    footer: { text: `alert ${c.alert_key || 'n/a'} · human review decides any plan change` },
    timestamp: c.checked_at || new Date().toISOString(),
  };
}

const out = [];
for (const item of $input.all()) {
  const body = item.json || {};
  const clients = Array.isArray(body.clients) ? body.clients : [body];

  for (const c of clients) {
    if (!shouldNotify(c)) continue;
    out.push({
      json: {
        username: 'Klaviyo Billing',
        embeds: [c.success === false ? failureEmbed(c) : reminderEmbed(c)],
      },
    });
  }
}
return out;
